css:
/* 1. Category tab horizontal scrollable wrapper */
.category-tab-container-snippet {
    width: 100%;
    overflow-x: auto;
    white-space: nowrap;
    -webkit-overflow-scrolling: touch;
    padding-left: 20px;
    padding-right: 20px;
    padding-top: 16px;
    padding-bottom: 8px;
    justify-content: flex-start;
    align-items: center;
    gap: 8px;
    display: inline-flex;
    margin-top: 0;
    margin-bottom: 8px;
    border-bottom: 1px solid #f1f5f9;
    scrollbar-width: none;
}
.category-tab-container-snippet::-webkit-scrollbar { display: none; }

/* 2. Coverage Details Container Card */
.coverage-detail-card {
    width: calc(100% - 40px);
    margin-left: 20px;
    margin-right: 20px;
    margin-top: 12px;
    padding: 16px;
    border-radius: 12px;
    border: 1px solid #E8EAF3;
    flex-direction: column;
    justify-content: flex-start;
    align-items: flex-start;
    gap: 16px;
    display: inline-flex;
    background: #ffffff;
    box-shadow: 0 4px 12px rgba(88, 93, 203, 0.02);
}

.coverage-detail-card:last-of-type {
    margin-bottom: 32px;
}

.coverage-detail-item {
    align-self: stretch;
    flex-direction: column;
    justify-content: flex-start;
    align-items: flex-start;
    gap: 8px;
    display: flex;
}

.coverage-item-title { 
    color: #212121; 
    font-size: 14px; 
    font-weight: 500; 
}

.coverage-item-values-row {
    align-self: stretch;
    display: inline-flex;
}

.coverage-value-col {
    flex: 1;
    display: inline-flex;
    flex-direction: column;
    gap: 2px;
}

.coverage-value-label { color: #777777; font-size: 10px; }
.coverage-value-amount { color: #212121; font-size: 16px; font-weight: 500; }
.coverage-divider { align-self: stretch; height: 1px; background: #E8EAF3; }

/* 3. Premium Plan Comparison Cards */
.plan-comparison-container { display: flex; flex-direction: column; gap: 12px; width: 100%; padding: 20px 0; }
.plan-title { color: #212121; font-size: 18px; font-weight: 700; padding: 0 20px; }
.plan-cards-row { display: flex; gap: 8px; width: 100%; overflow-x: auto; padding: 4px 20px 16px; scrollbar-width: none; }
.plan-cards-row::-webkit-scrollbar { display: none; }
.plan-card { width: 250px; flex-shrink: 0; padding: 20px; background: #ffffff; border-radius: 16px; border: 1px solid #DEDEDE; display: flex; gap: 12px; cursor: pointer; transition: all 0.25s ease; }
.plan-card.active-plan { border-color: #585DCB; box-shadow: 0 4px 14px rgba(88, 93, 203, 0.08); outline: 1px #585DCB solid; outline-offset: -1px; }
.plan-checkbox { width: 20px; height: 20px; border-radius: 4px; border: 1px solid #DEDEDE; background: #ffffff; flex-shrink: 0; position: relative; }
.plan-card.active-plan .plan-checkbox { background: #585DCB; border-color: #585DCB; }
.plan-checkbox::after { content: ''; position: absolute; left: 6px; top: 2px; width: 5px; height: 9px; border: solid #ffffff; border-width: 0 2px 2px 0; transform: rotate(45deg) scale(0); transition: transform 0.2s ease; }
.plan-card.active-plan .plan-checkbox::after { transform: rotate(45deg) scale(1); }
.plan-info-body { flex: 1; display: flex; flex-direction: column; gap: 16px; }
.plan-tags-row { display: flex; flex-wrap: wrap; gap: 4px; }
.plan-tag { padding: 2px 4px; border-radius: 4px; font-size: 10px; font-weight: 500; }
.plan-tag.new-coverage { background: #FBE9EE; color: #BB4885; }
.plan-tag.year-expiry { background: #F4EAFC; color: #7D4B9A; }
.plan-tag.age-expiry { background: #DDF3E6; color: #4E9586; }
.plan-tag.no-cancel { background: #FDF1D7; color: #CE9A26; }
.plan-name { color: #212121; font-size: 14px; font-weight: 700; line-height: 20px; word-break: keep-all; white-space: normal; }
.plan-price-row { display: flex; justify-content: space-between; align-items: center; gap: 10px; }
.plan-price-label { color: #777777; font-size: 12px; }
.plan-price-value { color: #585DCB; font-size: 18px; font-weight: 700; }

/* 4. Plan Detailed Coverage Accordion */
.plan-accordion-container { width: 100%; padding: 20px; background: #ffffff; border-radius: 16px; border: 1px solid #DEDEDE; display: flex; flex-direction: column; gap: 12px; transition: all 0.3s ease; }
.plan-accordion-container.active-plan { border-color: #DE4336; box-shadow: 0 4px 14px rgba(222, 67, 54, 0.05); outline: 1px #DE4336 solid; outline-offset: -1px; }
.plan-accordion-header { width: 100%; display: flex; gap: 12px; cursor: pointer; }
.plan-accordion-checkbox { width: 20px; height: 20px; background: #DE4336; border-radius: 4px; flex-shrink: 0; position: relative; display: flex; justify-content: center; align-items: center; transition: all 0.25s ease; }
.plan-accordion-checkbox::after { content: ''; position: absolute; left: 6px; top: 2px; width: 5px; height: 9px; border: solid #ffffff; border-width: 0 2px 2px 0; transform: rotate(45deg) scale(0); transition: transform 0.2s ease; }
.plan-accordion-container.active-plan .plan-accordion-checkbox::after { transform: rotate(45deg) scale(1); }
.plan-accordion-container:not(.active-plan) .plan-accordion-checkbox { background: #ffffff; border: 1px solid #DEDEDE; }
.plan-accordion-body { flex: 1; display: flex; flex-direction: column; gap: 16px; }
.plan-detail-panel { align-self: stretch; padding-left: 32px; display: flex; flex-direction: column; gap: 12px; max-height: 2000px; opacity: 1; overflow: hidden; transition: all 0.4s ease; }
.plan-detail-panel.collapsed { max-height: 0; opacity: 0; margin-top: -12px; pointer-events: none; }
.plan-detail-info-pill { align-self: stretch; padding: 8px 12px; background: #FDF1F0; border-radius: 8px; display: flex; flex-direction: column; }
.plan-detail-info-text { align-self: stretch; color: #212121; font-size: 10px; font-weight: 500; }
.plan-detail-category-header { align-self: stretch; color: #DE4336; font-size: 10px; font-weight: 700; }
.plan-detail-item { align-self: stretch; display: flex; flex-direction: column; gap: 8px; }
.plan-detail-item-title { align-self: stretch; color: #212121; font-size: 12px; font-weight: 500; }
.plan-detail-item-values { align-self: stretch; display: flex; }
.plan-detail-val-col { flex: 1; display: flex; flex-direction: column; gap: 2px; }
.plan-detail-val-label { align-self: stretch; color: #777777; font-size: 10px; }
.plan-detail-val-amount { align-self: stretch; color: #212121; font-size: 14px; font-weight: 500; }
.plan-accordion-toggle-btn { align-self: stretch; justify-content: center; align-items: center; gap: 4px; display: flex; cursor: pointer; }
.plan-accordion-toggle-text { color: #777777; font-size: 12px; font-weight: 500; }
.plan-accordion-toggle-icon { width: 16px; height: 16px; display: flex; align-items: center; justify-content: center; transition: transform 0.3s ease; }

/* 5. Diagnosis Coverage Status Dashboard */
.diag-status-container { width: 100%; padding: 20px; display: flex; flex-direction: column; gap: 12px; }
.diag-title-row { align-self: stretch; justify-content: flex-start; align-items: center; gap: 8px; display: inline-flex; }
.diag-icon-circle { width: 32px; height: 32px; position: relative; background: #F6F6F6; border-radius: 999px; flex-shrink: 0; }
.diag-title-text { flex: 1; color: #212121; font-size: 16px; font-weight: 700; }
.diag-items-stack { align-self: stretch; flex-direction: column; justify-content: center; align-items: flex-start; gap: 8px; display: flex; }
.diag-item-row { align-self: stretch; min-width: 156px; padding: 7px 16px; background: #ffffff; border-radius: 8px; border: 1px solid #E8EAF3; justify-content: space-between; align-items: center; display: inline-flex; transition: all 0.2s ease; cursor: pointer; }
.diag-item-row:hover { transform: translateY(-1px); border-color: #D3D5E4; box-shadow: 0 4px 10px rgba(88, 93, 203, 0.03); }
.diag-item-name { color: #212121; font-size: 14px; font-weight: 500; }
.diag-badge { padding: 4px 12px; border-radius: 999px; display: flex; }
.diag-badge.deficient { background: #FCEEF1; color: #DC3B5E; }
.diag-badge.deficient::before { content: ''; width: 4px; height: 4px; background: #DC3B5E; border-radius: 50%; margin-right: 4px; display: inline-block; align-self: center; }
.diag-badge.unsubscribed { background: #F6F6F6; color: #777777; }
.diag-badge.unsubscribed::before { content: ''; width: 4px; height: 4px; background: #999999; border-radius: 50%; margin-right: 4px; display: inline-block; align-self: center; }
